CREATE OR REPLACE FUNCTION manager_name(p_department_id IN NUMBER) RETURN VARCHAR2 IS
  l_name employees.last_name%TYPE;
BEGIN
  SELECT e.last_name INTO l_name
    FROM departments d JOIN employees e ON e.employee_id = d.manager_id
   WHERE d.department_id = p_department_id;
  RETURN l_name;
EXCEPTION
  WHEN NO_DATA_FOUND THEN RETURN NULL;
END manager_name;

CREATE OR REPLACE PROCEDURE harness_app.archive_old_orders(
  p_before_date IN DATE
)
AS
  TYPE t_orders IS TABLE OF harness_app.orders%ROWTYPE;
  l_batch t_orders;

  CURSOR c_old_orders IS
    SELECT o.*
      FROM harness_app.orders o
     WHERE o.order_date < p_before_date
     ORDER BY o.order_id;
BEGIN
  OPEN c_old_orders;

  LOOP
    FETCH c_old_orders
      BULK COLLECT INTO l_batch
      LIMIT 10000;

    EXIT WHEN l_batch.COUNT = 0;

    FORALL i IN 1 .. l_batch.COUNT
      INSERT INTO harness_app.orders_archive (
        order_id,
        customer_id,
        order_date,
        status,
        total
      )
      VALUES (
        l_batch(i).order_id,
        l_batch(i).customer_id,
        l_batch(i).order_date,
        l_batch(i).status,
        l_batch(i).total
      );

    FORALL i IN 1 .. l_batch.COUNT
      DELETE FROM harness_app.orders o
       WHERE o.order_id = l_batch(i).order_id;
  END LOOP;

  CLOSE c_old_orders;
END archive_old_orders;
