  /* Check 1: a department_id that has at least one matching employee row. */
  SELECT MIN(department_id)
    INTO l_match_dept
    FROM employees
   WHERE department_id IS NOT NULL;

  IF l_match_dept IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('FAIL: matching department_id check: no non-NULL department_id row found in employees.');
    l_failures := l_failures + 1;
  ELSE
    SELECT COUNT(*)
      INTO l_expected
      FROM employees
     WHERE department_id = l_match_dept;

    l_actual := HARNESS_APP.headcount(l_match_dept);

    IF l_actual = l_expected THEN
      DBMS_OUTPUT.PUT_LINE('PASS: matching department_id check: department_id=' || l_match_dept ||
                           ', expected=' || l_expected ||
                           ', actual=' || l_actual);
    ELSE
      DBMS_OUTPUT.PUT_LINE('FAIL: matching department_id check: department_id=' || l_match_dept ||
                           ', expected=' || l_expected ||
                           ', actual=' || l_actual);
      l_failures := l_failures + 1;
    END IF;
  END IF;

  /* Check 2: a department_id that matches no employee row. */
  l_no_match_dept := NULL;

  FOR i IN 1..10 LOOP
    SELECT COUNT(*)
      INTO l_count
      FROM employees
     WHERE department_id = -i;

    IF l_count = 0 THEN
      l_no_match_dept := -i;
      EXIT;
    END IF;
  END LOOP;

  IF l_no_match_dept IS NULL THEN
    DBMS_OUTPUT.PUT_LINE('FAIL: no-match department_id check: no unused negative department_id candidate was found among -1 through -10.');
    l_failures := l_failures + 1;
