    SELECT COUNT(*)
      INTO l_expected
      FROM employees
     WHERE department_id = l_no_match_dept;

    l_actual := HARNESS_APP.headcount(l_no_match_dept);

    IF l_actual = l_expected THEN
      DBMS_OUTPUT.PUT_LINE('PASS: no-match department_id check: department_id=' || l_no_match_dept ||
